package it.carmine.streamplayer;
import android.app.*;
import android.content.*;
import android.graphics.Color;
import android.graphics.drawable.ColorDrawable;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.util.*;
import java.util.concurrent.*;
import it.carmine.streamplayer.lab211.*;

/** New 2.1.11 pipeline. Streaming Community and VixSrc stay in their original activity. */
public final class LabMultiCatalogActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();
 private final List<String> log=new ArrayList<>();
 private final List<LabPipeline.Title> titles=new ArrayList<>();
 private LinearLayout root;private FrameLayout body;private TextView state;private EditText search;
 private ArtworkStore artwork;private LabPipeline pipeline;private LabPipeline.CatalogAdapter adapter;
 private String base,name,kind;private boolean closed,detail;private int generation;private final ThreadLocal<Integer> taskGeneration=new ThreadLocal<>();
 private int dp(int x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
 private TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(Color.WHITE);return t;}
 private Button button(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);return b;}
 private void append(LinearLayout p,View v){p.addView(v,new LinearLayout.LayoutParams(-1,-2));}
 private void event(LabPipeline.Stage stage,String code,String message){synchronized(log){if(log.size()>=150)log.remove(0);log.add(stage+" · "+code+" · "+message);}Integer token=taskGeneration.get();runOnUiThread(()->{if(!closed&&(token==null||token==generation))state.setText(stage+" · "+code+" · "+message);});}
 private <T> void job(String message,Callable<T> task,java.util.function.Consumer<T> done){int current=++generation;state.setText(message);worker.execute(()->{taskGeneration.set(current);try{T value=task.call();runOnUiThread(()->{if(!closed&&current==generation)done.accept(value);});}catch(Exception e){runOnUiThread(()->{if(!closed&&current==generation){String msg=e instanceof LabPipeline.Failure?((LabPipeline.Failure)e).stage+" · "+((LabPipeline.Failure)e).code+" · "+e.getMessage():"LAB · "+e.getClass().getSimpleName();state.setText(msg);synchronized(log){log.add(msg);}}});}});}
 @Override public void onCreate(Bundle saved){super.onCreate(saved);getWindow().getDecorView().setSystemUiVisibility(5894);
  base=getIntent().getStringExtra("lab_url");name=getIntent().getStringExtra("lab_name");kind=getIntent().getStringExtra("lab_adapter");
  root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(18),dp(12),dp(18),dp(12));root.setBackgroundColor(0xff10151c);setContentView(root);append(root,text("LAB 2.1.15 · "+name,22));state=text("Catalogo…",14);append(root,state);
  LinearLayout actions=new LinearLayout(this);append(root,actions);Button providers=button("← Provider"),diagnostic=button("Diagnostica"),reload=button("Ricarica");for(Button b:new Button[]{providers,diagnostic,reload})actions.addView(b,new LinearLayout.LayoutParams(0,dp(48),1));providers.setOnClickListener(v->finish());reload.setOnClickListener(v->load(""));diagnostic.setOnClickListener(v->{String all;synchronized(log){all=String.join("\n",log);}TextView t=text(all,13);ScrollView s=new ScrollView(this);s.addView(t);new AlertDialog.Builder(this).setTitle("Fasi della pipeline LAB").setView(s).setPositiveButton("Chiudi",null).show();});
  search=new EditText(this);search.setSingleLine(true);search.setTextColor(Color.WHITE);search.setHintTextColor(0xffaaaaaa);search.setHint("Cerca nel provider");append(root,search);LinearLayout searchActions=new LinearLayout(this);append(root,searchActions);Button find=button("Cerca"),testSource=button("Prova URL host");for(Button b:new Button[]{find,testSource})searchActions.addView(b,new LinearLayout.LayoutParams(0,dp(48),1));find.setOnClickListener(v->{((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(search.getWindowToken(),0);load(search.getText().toString().trim());});testSource.setOnClickListener(v->{EditText input=new EditText(this);input.setSingleLine(true);input.setHint("https://… collegamento host o media");input.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Prova una fonte nel LAB").setView(input).setPositiveButton("Verifica e riproduci",null).setNegativeButton("Annulla",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(ok->{String url=input.getText().toString().trim();try{LabPipeline.https(url);dialog.dismiss();resolve(new LabPipeline.Source(url,LabPipeline.host(url),base));}catch(Exception e){input.setError("Inserisci un singolo URL HTTPS valido");}}));dialog.show();});
  body=new FrameLayout(this);root.addView(body,new LinearLayout.LayoutParams(-1,0,1));artwork=new ArtworkStore(this,true);
  pipeline=new LabPipeline(new LabHttp(),this::event);
  try{LabPipeline.https(base);adapter="json".equals(kind)?new JsonCatalog():LabPipeline.adapter(kind);load("");}catch(Exception e){state.setText(e.getMessage());}
 }
 private void load(String query){detail=false;job("CATALOG · caricamento "+name,()->pipeline.catalog(adapter,base,query),found->{titles.clear();for(LabPipeline.Title t:found)if(!"json".equals(kind)||query.isEmpty()||t.name.toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT)))titles.add(t);renderCatalog();});}
 private void renderCatalog(){detail=false;body.removeAllViews();state.setText("CATALOG · "+titles.size()+" titoli · "+adapter.name());GridView grid=new GridView(this);grid.setNumColumns(4);grid.setDrawSelectorOnTop(true);grid.setSelector(new ColorDrawable(0x66ffbd59));grid.setHorizontalSpacing(dp(10));grid.setVerticalSpacing(dp(10));grid.setAdapter(new BaseAdapter(){public int getCount(){return titles.size();}public Object getItem(int i){return titles.get(i);}public long getItemId(int i){return i;}public View getView(int i,View old,ViewGroup parent){LinearLayout card=new LinearLayout(LabMultiCatalogActivity.this);card.setOrientation(1);card.setPadding(dp(5),dp(5),dp(5),dp(5));card.setBackgroundColor(0xff243343);ImageView image=new ImageView(LabMultiCatalogActivity.this);image.setScaleType(ImageView.ScaleType.FIT_CENTER);card.addView(image,new LinearLayout.LayoutParams(-1,dp(165)));LabPipeline.Title t=titles.get(i);artwork.bind(image,t.poster,new ColorDrawable(0xff354354));TextView label=text(t.name,14);label.setMaxLines(2);card.addView(label,new LinearLayout.LayoutParams(-1,dp(48)));return card;}});grid.setOnItemClickListener((p,v,index,id)->open(titles.get(index)));body.addView(grid);grid.requestFocus();}
 private void open(LabPipeline.Title title){detail=true;body.removeAllViews();LinearLayout list=new LinearLayout(this);list.setOrientation(1);ScrollView scroll=new ScrollView(this);scroll.addView(list);body.addView(scroll);append(list,text(title.name,22));Button back=button("← Locandine");append(list,back);back.setOnClickListener(v->{generation++;renderCatalog();});
  job("HOST_SEARCH · lettura scheda",()->pipeline.sourceReport(adapter,title),report->{state.setText("HOST_SEARCH · "+report.sources.size()+" collegamenti candidati · "+report.trailers.size()+" trailer/YouTube");
   if(report.sources.isEmpty())append(list,text(report.trailers.isEmpty()?"Nessuna fonte del titolo individuata nel markup pubblico. Il layout può richiedere un adattatore ulteriore.":"Trovati soltanto trailer/YouTube. Non è stata individuata una fonte del film o episodio.",16));
   if(!report.sources.isEmpty())append(list,text("Tieni premuta una fonte per vedere e copiare il collegamento.",13));
   for(LabPipeline.Source source:report.sources){Button row=button(source.label+"\n"+LabPipeline.sourceStatus(source)+" · "+LabPipeline.host(source.url));append(list,row);row.setOnClickListener(v->resolve(source));row.setOnLongClickListener(v->{TextView link=text(source.url,14);link.setTextIsSelectable(true);link.setPadding(dp(16),dp(12),dp(16),dp(12));new AlertDialog.Builder(this).setTitle(source.label+" · collegamento selezionato").setView(link).setPositiveButton("Copia URL",(d,w)->{((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Fonte LAB",source.url));Toast.makeText(this,"Collegamento copiato",Toast.LENGTH_SHORT).show();}).setNegativeButton("Chiudi",null).show();return true;});}
   if(!report.trailers.isEmpty()){append(list,text("TRAILER / YOUTUBE · separati dalle fonti del titolo",15));for(LabPipeline.Source source:report.trailers)append(list,text(source.label+" · "+LabPipeline.host(source.url)+" · escluso dal player interno",14));}
  });
 }
 private void resolve(LabPipeline.Source source){job("RESOLVER · "+LabPipeline.host(source.url),()->pipeline.resolve(source),media->{state.setText("SOURCE · verificata · "+media.host+" · "+media.mime);Intent intent=new Intent(this,LabMultiPlayerActivity.class).putExtra("stream_url",media.url).putExtra("stream_mime",media.mime).putExtra("stream_referer",media.referer);ArrayList<String> urls=new ArrayList<>(),langs=new ArrayList<>(),labels=new ArrayList<>(),mimes=new ArrayList<>();for(LabPipeline.Subtitle s:media.subtitles){urls.add(s.url);langs.add(s.language);labels.add(s.label);mimes.add(s.mime);}intent.putStringArrayListExtra("sub_urls",urls).putStringArrayListExtra("sub_langs",langs).putStringArrayListExtra("sub_labels",labels).putStringArrayListExtra("sub_mimes",mimes);startActivity(intent);});}
 @Override public void onBackPressed(){if(detail){generation++;renderCatalog();}else super.onBackPressed();}
 @Override protected void onDestroy(){closed=true;generation++;worker.shutdownNow();if(artwork!=null)artwork.close();super.onDestroy();}
}
